def icon(name, cls=''):
    path=paths.get(name,paths['arrow'])
    return f'<svg aria-hidden="true" class="{cls}" xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{path}</svg>'

def button(label,href='contact.html',variant='',extra=''):
    return f'<a class="btn {variant}" href="{href}" {extra}>{escape(label)} {icon("arrow-up-right")}</a>'

def section_header(kicker,title,desc='',align=''):
    return f'<div class="section-head {align}"><div><span class="kicker">{escape(kicker)}</span><h2>{title}</h2></div>'+(f'<p>{desc}</p>' if desc else '')+'</div>'

