    intro_script = '<script src="assets/intro.js?v=20261122-viewport2" defer></script>' if is_home else ''
    canonical=BASE+('' if page=='index' else page+'.html')
    og=escape(description,quote=True)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#07162d"><meta name="description" content="{og}"><meta name="robots" content="index,follow"><title>{escape(title)} | QBranch Uganda Limited</title><link rel="canonical" href="{canonical}"><link rel="icon" href="Qbranch-logo.png" type="image/png"><link rel="preconnect" href="https://fonts.googleapis.com"><link rel="preconnect" href="https://fonts.gstatic.com" crossorigin><link rel="preconnect" href="https://images.unsplash.com"><link rel="stylesheet" href="assets/site.css?v=20261122-viewport2"><link rel="stylesheet" href="assets/showcase.css?v=20261123-showcase1">{intro_head}<meta property="og:title" content="{escape(title,quote=True)} | QBranch Uganda Limited"><meta property="og:description" content="{og}"><meta property="og:type" content="website"><meta property="og:url" content="{canonical}"><meta property="og:image" content="{BASE}Qbranch-logo.png"><meta name="twitter:card" content="summary"><script type="application/ld+json">{json.dumps({'@context':'https://schema.org','@type':'Organization','name':'QBranch Uganda Limited','url':BASE,'logo':BASE+'Qbranch-logo.png','email':'info@qbranch.co.ug','telephone':'+256414672342','address':{'@type':'PostalAddress','streetAddress':'Plot 47/49, Uganda Cooperative Alliance Building, Nkrumah Road','addressLocality':'Kampala','addressCountry':'UG'}},ensure_ascii=False)}</script></head><body data-page="{page}"><a class="skip-link" href="#main-content" style="position:absolute;left:-9999px;top:5px;z-index:200;background:#fff;padding:10px" onfocus="this.style.left='10px'" onblur="this.style.left='-9999px'">Skip to main content</a>{intro_markup}{header(page)}<main id="main-content">{main}</main>{footer()}{intro_script}<script src="assets/showcase.js?v=20261123-showcase1" defer></script></body></html>'''

